import System.Int32;import System.SByte;import System.UInt16;import System.UInt32;import System.OverflowException;import System.FormatException;import System.Byte;import System.FormatException;import System.ReadOnlySpan;import System.Globalization.NumberStyles;import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.Decimal;import System.IComparable;import System.IFormattable;import System.IFormatProvider;import System.InvalidOperationException;import java.nio.file.*;import java.util.*;
class Int32StringCharParserAlignmentProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static NumberFormatInfo custom(){NumberFormatInfo n=new NumberFormatInfo();n.set_NegativeSign("~");n.set_PositiveSign("^");n.set_NumberDecimalSeparator("@");n.set_NumberGroupSeparator("_");n.set_NumberGroupSizes(new int[]{2,3});n.set_CurrencySymbol("USD");n.set_CurrencyDecimalSeparator(":");n.set_CurrencyGroupSeparator("'");n.set_CurrencyGroupSizes(new int[]{3,2});n.set_CurrencyPositivePattern(2);n.set_CurrencyNegativePattern(14);n.set_NumberNegativePattern(4);n.set_PercentSymbol("%!");return n;}
 static String compare(IComparable value,Object other){try{return "OK|"+value.CompareTo(other);}catch(Exception e){return error(e);}}
 static String format(IFormattable value,String f,IFormatProvider provider){try{return "OK|"+units(value.ToString(f,provider));}catch(Exception e){return error(e);}}
 static String error(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),"~");}
 static final class Actor implements IFormatProvider{int calls;Type last;Object result;Exception failure;NumberFormatInfo format=new NumberFormatInfo();Actor(String[] p){format.set_NegativeSign(text(p[5]));format.set_PositiveSign(text(p[6]));format.set_NumberDecimalSeparator(text(p[7]));format.set_NumberGroupSeparator(text(p[8]));format.set_CurrencySymbol(text(p[9]));format.set_CurrencyDecimalSeparator(text(p[10]));format.set_CurrencyGroupSeparator(text(p[11]));format.set_NumberNegativePattern(Integer.parseInt(p[12]));if(p[4].equals("custom"))result=format;if(p[4].equals("wrong"))result="wrong";if(p[4].equals("throwing"))failure=new InvalidOperationException("provider failure");if(p[4].equals("format-throwing"))failure=new FormatException("provider format failure");if(p[4].equals("overflow-throwing"))failure=new OverflowException("provider overflow failure");}public Object GetFormat(Type type){calls++;last=type;if(failure!=null)throw failure;return result;}}
 public static void main(String[] args)throws java.lang.Exception{int calls=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);Actor provider=new Actor(p);NumberStyles style=NumberStyles.FromInt32(Integer.parseInt(p[1]));String input=text(p[2]),content=input==null?"":input;char[] backing=("BAD"+content+"BAD").toCharArray(),before=backing.clone();ReadOnlySpan<Character> span=ReadOnlySpan.OfChars(backing,3,content.length());Int32[] holder={new Int32(123)};String actual;Exception thrown=null;try{if(p[3].equals("1")){boolean ok=p[18].equals("chars")?Int32.TryParse(span,style,provider,holder):Int32.TryParse(input,style,provider,holder);actual="OK|"+flag(ok);}else{Int32 value=p[18].equals("chars")?Int32.Parse(span,style,provider):Int32.Parse(input,style,provider);actual="OK|"+value.get_Value();}}catch(Exception e){thrown=e;actual=error(e);}check(actual,p[13],line);check(Integer.toString(holder[0].get_Value()),p[14],"holder");check(Integer.toString(provider.calls),p[15],"callback count");check(flag(provider.last==Type.GetType("System.Globalization.NumberFormatInfo")),p[16],"requested type");check(flag(provider.failure!=null&&thrown==provider.failure),p[17],"provider identity");if(!java.util.Arrays.equals(before,backing))throw new AssertionError("Char input mutated");check(provider.format.get_NegativeSign(),text(p[5]),"negative unchanged");check(provider.format.get_PositiveSign(),text(p[6]),"positive unchanged");check(provider.format.get_NumberDecimalSeparator(),text(p[7]),"decimal unchanged");check(provider.format.get_NumberGroupSeparator(),text(p[8]),"group unchanged");check(provider.format.get_CurrencySymbol(),text(p[9]),"currency unchanged");groups+=5;calls++;}java.lang.System.out.println("PASS Int32 String/Char aligned calls="+calls+" groups="+groups);}}
